// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 a1, uint256 a2, address actor) public {
        vm.assume(a1 <= VALUE_CAP);
        vm.assume(a2 <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        a1 = bound(a1, 0, 1e30);
        a2 = bound(a2, 0, 1e30);

        vm.deal(actor, a1 + a2);
        vm.prank(actor);
        c.addToBalance{value: a1}();
        uint256 first = c.getBalance(actor);

        vm.prank(actor);
        c.addToBalance{value: a2}();
        uint256 second = c.getBalance(actor);

        assertTrue(first == a1 && second >= first && second >= a2 && (a2 == 0 ? second == first : second > first) && second == first + a2 - (first + a2 - second), "balance must accumulate");
    }
}
